SQL_DOC.P_SQL:
SELECT PODT.PLANT , IVDT.INV_NO AS LEGACY_IV_NO , IVDT.INV_SEQ AS LEGACY_IV_SEQ , IVDT.STATUS , PRDT.LEGACY_PO_NO , PRDT.LEGACY_PO_SEQ , PODT.REF_IF_NO AS LEGACY_PO_COUNT , PODT.BUYER_ITEM_NO , IVDT.INV_QTY AS ITEM_QTY , IVDT.INVOICE_DATE AS INV_DATE FROM ICOMIVHD IVHD, ICOMIVDT IVDT, ICOMPODT PODT, ICOMPRDT PRDT WHERE IVHD.BUYER = '$G_RS.BUYER$' AND IVHD.INV_NO = '$G_RS.INV_NO$' AND IVHD.SND_CHK = 'N' AND IVHD.BUYER = IVDT.BUYER AND IVHD.INV_NO= IVDT.INV_NO AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ= PODT.PO_SEQ AND PODT.PLANT IS NOT NULL AND PODT.PLANT IN ('A0','B0','C0','D0') AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ UNION ALL SELECT PODT.PLANT , IVDT.INV_NO AS LEGACY_IV_NO , IVDT.INV_SEQ AS LEGACY_IV_SEQ , IVDT.STATUS , PRDT.LEGACY_PO_NO , PRDT.LEGACY_PO_SEQ , PODT.REF_IF_NO AS LEGACY_PO_COUNT , PODT.BUYER_ITEM_NO , IVDT.INV_QTY AS ITEM_QTY , IVDT.INV_DATE AS INV_DATE FROM WMSIVDT IVDT, ICOMPODT PODT, ICOMPRDT PRDT WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' AND IVDT.SND_CHK = 'N' AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ= PODT.PO_SEQ AND PODT.PLANT IS NOT NULL AND PODT.PLANT IN ('A0','B0','C0','D0') AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ
DECLARE BEGIN IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVHD SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$'; END IF; END;
DECLARE BEGIN IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVHD SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$'; END IF; END;
